fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    // Clone the input to start with the same elements
    let mut result = a.clone();

    // Only swap if there are at least two elements
    if result.len() > 1 {
        let last_index = result.len() - 1;
        result.swap(0, last_index);
    }

    result
}

